const {chromium}=require('playwright'),assert=require('node:assert/strict'),fs=require('node:fs');
const base=process.env.SKY_TEST_URL||'http://127.0.0.1:8766/tower-of-babel/';
(async()=>{const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});try{const p=await browser.newPage({viewport:{width:1100,height:850},hasTouch:true}),errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('console',m=>{if(m.type()==='error'&&m.text().includes('failed to load'))errors.push(m.text())});await p.addInitScript(()=>{requestAnimationFrame=()=>0});await p.route('**/game-v74-meadow.txt*',async r=>{const s=await r.fetch();await r.fulfill({response:s,body:await s.text()+`\nskySeedV62=7;window.meadowTest={screen(x){cam.x=x*B+B/2;cam.anim=false;cameraSpringActiveV24=false;return w2s(x*B+B/2,-6)},flowers(){wildlifeV71=[];return [...flowersV74.values()].filter(f=>{const p=w2s(f.x*B+B/2,-6);return !structuresV46.some(b=>f.x*B>=b.x&&f.x*B<b.x+STRUCTURES_V46[b.type].w*B)})},mine(x){harvest(grid.get(key(x,0)))},inventory(){refreshPickerV68();return [...$('itemChoicesV68').children].map(b=>b.dataset.item)},population(){const previous=wildlifeSeedReadyV71;wildlifeSeedReadyV71=true;wildlifeV71=[];wildlifeHabitatsV71.clear();for(let ch=100;ch<400;ch++){generated.add(ch);cam.x=(ch+.5)*24*B;seedWildlifeV71()}wildlifeSeedReadyV71=previous;return{count:wildlifeV71.length,habitats:wildlifeHabitatsV71.size,ids:[...new Set(wildlifeV71.map(a=>a.species))],definitions:Object.keys(WILDLIFE_SPECIES_V71)}},save:saveGame,pan(y){cam.y=y;cam.anim=false;__buttonwood.render(performance.now())},hud(){let reads=0,encodes=0;const read=Element.prototype.getBoundingClientRect,encode=HTMLCanvasElement.prototype.toDataURL;Element.prototype.getBoundingClientRect=function(...a){reads++;return read.apply(this,a)};HTMLCanvasElement.prototype.toDataURL=function(...a){encodes++;return encode.apply(this,a)};for(let i=0;i<120;i++)refreshCrittersV73();Element.prototype.getBoundingClientRect=read;HTMLCanvasElement.prototype.toDataURL=encode;return{reads,encodes}}};`})});
const load=async()=>{await p.goto(base+'?sample=buttonwood');await p.waitForFunction(()=>window.meadowTest,null,{polling:100})};await load();assert.deepEqual(await p.evaluate(()=>meadowTest.hud()),{reads:0,encodes:0});
let plants=await p.evaluate(()=>meadowTest.flowers());assert(plants.length>=2,'visible flowers');const before=await p.evaluate(()=>skyStackMeadow.state.count),x=plants[0].x,q=await p.evaluate(x=>meadowTest.screen(x),x);await p.mouse.click(q.x,q.y);assert.equal(await p.evaluate(()=>skyStackMeadow.state.count),before+1);assert(await p.evaluate(()=>meadowTest.inventory().includes('flowers')));
const drag=plants[1].x,d=await p.evaluate(x=>meadowTest.screen(x),drag);await p.mouse.move(d.x,d.y);await p.mouse.down();await p.mouse.move(d.x+25,d.y+10,{steps:4});await p.mouse.up();assert.equal(await p.evaluate(()=>skyStackMeadow.state.count),before+1,'drag does not harvest');
await p.evaluate(x=>meadowTest.mine(x),drag);assert.equal(await p.evaluate(()=>skyStackMeadow.state.count),before+2);assert.equal(await p.evaluate(x=>skyStackMeadow.collect(x),drag),false,'no duplicate');await p.evaluate(()=>meadowTest.save());await load();assert.equal(await p.evaluate(()=>skyStackMeadow.state.count),before+2);assert.equal(await p.evaluate(x=>skyStackMeadow.state.flowers.some(f=>f.x===x),x),false,'picked flowers stay picked');
const touchPlant=(await p.evaluate(()=>meadowTest.flowers()))[0];assert(touchPlant);const touchPoint=await p.evaluate(x=>meadowTest.screen(x),touchPlant.x),cdp=await p.context().newCDPSession(p);const touches=[{x:touchPoint.x,y:touchPoint.y,id:1}];await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:touches});await cdp.send('Input.dispatchTouchEvent',{type:'touchCancel',touchPoints:[]});assert.equal(await p.evaluate(()=>skyStackMeadow.state.count),before+2);await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:touches});await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[...touches,{x:touchPoint.x+40,y:touchPoint.y,id:2}]});await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});assert.equal(await p.evaluate(()=>skyStackMeadow.state.count),before+2,'pinch does not gather');await cdp.detach();await p.touchscreen.tap(touchPoint.x,touchPoint.y);assert.equal(await p.evaluate(()=>skyStackMeadow.state.count),before+3,'touch harvest');
// Record real layer paint coordinates: near and distant ridges travel at different depths.
const depth=await p.evaluate(()=>{const calls=y=>{const records=[],g={globalAlpha:1,save(){},restore(){},fillRect(x,y,w,h){records.push([x,y,w,h])}};ButtonwoodArt.paintBiomeScenery(g,{width:300,height:400,ground:200-y,camX:0,camY:y,state:ButtonwoodArt.skyState(60),weights:{mountains:1},seed:7});return records};const a=calls(0),b=calls(-100);return[a[0][1],b[0][1]]});assert(Math.abs(depth[1]-depth[0]-3.5)<2,'distant peaks move 3.5% vertically');
fs.mkdirSync('tower-of-babel/buttonwood/qa/meadow',{recursive:true});await p.evaluate(()=>{meadowTest.pan(-25)});await p.screenshot({path:'tower-of-babel/buttonwood/qa/meadow/surface.png'});await p.evaluate(()=>meadowTest.pan(-300));await p.screenshot({path:'tower-of-babel/buttonwood/qa/meadow/ascent.png'});
const pop=await p.evaluate(()=>meadowTest.population());assert.equal(pop.definitions.length,31);assert.equal(pop.ids.length,31);assert(pop.count/pop.habitats<1.6,'sparse habitats');assert(pop.count/pop.habitats>=1);assert.deepEqual(errors,[]);console.log('PASS flowers tap/drag/support destruction/inventory/save, 31 wild species, sparse habitat counts, vertical depth, unchanged HUD performs zero image encodes/layout reads',JSON.stringify({count:pop.count,habitats:pop.habitats}));
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
